import math

class MiniSemanticSearch:
    def __init__(self, corpus: list[str]):
        self.corpus = corpus
        self.vectors = [self._encode(d) for d in corpus]

    def _encode(self, text: str) -> dict:
        counts = {}
        for w in text.lower().split():
            counts[w] = counts.get(w, 0) + 1
        return counts

    def _cosine(self, a: dict, b: dict) -> float:
        mag_a = math.sqrt(sum(v * v for v in a.values()))
        mag_b = math.sqrt(sum(v * v for v in b.values()))
        if mag_a == 0 or mag_b == 0:
            return 0.0
        dot = sum(v * b[k] for k, v in a.items() if k in b)
        return dot / (mag_a * mag_b)

    def search(self, query: str, top_k: int = 2) -> list[dict]:
        q = self._encode(query)
        scored = [
            {"doc": doc, "score": self._cosine(q, vec)}
            for doc, vec in zip(self.corpus, self.vectors)
        ]
        scored.sort(key=lambda x: x["score"], reverse=True)
        return scored[:top_k]

# Test it:
engine = MiniSemanticSearch([
    "reset my account password",
    "update my billing information",
    "how to optimize python performance",
    "make my python code run faster",
])

results = engine.search("speed up my python program", top_k=2)
print(len(results))
print(results[0]["score"] >= results[1]["score"])
print("python" in results[0]["doc"])

import math

class RankedRetriever:
    def __init__(self, corpus: list[str]):
        self.corpus = corpus
        self.vectors = [self._encode(d) for d in corpus]

    def _encode(self, text: str) -> dict:
        vec = {}
        for w in text.lower().split():
            vec[w] = vec.get(w, 0) + 1
        return vec

    def _cosine(self, a: dict, b: dict) -> float:
        shared = set(a) & set(b)
        dot = sum(a[w] * b[w] for w in shared)
        ma = math.sqrt(sum(v**2 for v in a.values()))
        mb = math.sqrt(sum(v**2 for v in b.values()))
        return dot / (ma * mb) if ma and mb else 0.0

    def _ranked(self, query: str) -> list[dict]:
        q = self._encode(query)
        scored = [{"doc": d, "score": self._cosine(q, v)}
                  for d, v in zip(self.corpus, self.vectors)]
        return sorted(scored, key=lambda r: r["score"], reverse=True)

    def top_match(self, query: str):
        ranked = self._ranked(query)
        return ranked[0]["doc"] if ranked else None

    def format_results(self, query: str, top_k: int = 3) -> str:
        ranked = self._ranked(query)[:max(top_k, 0)]
        lines = [f"{i}. [{r['score']:.2f}] {r['doc']}"
                 for i, r in enumerate(ranked, start=1)]
        return "\n".join(lines)

# Test it:
r = RankedRetriever([
    "python web development with flask",
    "data science with pandas and numpy",
    "build rest apis in python",
])
print(r.top_match("how to build an api"))
print(r.format_results("python data analysis", top_k=2))
